pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    B c;
    function setUp() public { c = new B(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
